// ============================================
// SELLER FOLLOW-UP ENGINE - SPEC COMPLIANT v4.0
// From: Follow_Up_Engine_Dev_Spec_v2.pdf
// 
// HARD RULES (Section 9):
// - NEVER send before 8 AM or after 8 PM EST
// - NEVER send on Sunday
// - Saturday: 10 AM - 6 PM only
// 
// SEND WINDOWS (randomized):
// - Morning: 8:30 AM - 10:30 AM
// - Midday: 11:30 AM - 1:30 PM
// - Afternoon: 2:30 PM - 4:30 PM
// - Evening: 5:30 PM - 7:30 PM
// ============================================

const now = new Date();

// Get EST time properly
const estString = now.toLocaleString('en-US', { timeZone: 'America/New_York' });
const estDate = new Date(estString);
const currentHourEST = estDate.getHours();
const currentMinuteEST = estDate.getMinutes();
const dayOfWeekEST = estDate.getDay(); // 0=Sun, 6=Sat

// Phone Number Configuration
const PHONE_CONFIG = {
  '330': [
    { id: 'phon_jIteklsdr2tUmnb09NjGuQYiPY1WylLCYAeIAyrZMe0', number: '+15555550100' },
    { id: 'phon_uFcxzUFdhi1ZQl1BHaqoANc2fNacsViMtUIvYpMAV7j', number: '+15555550100' },
    { id: 'phon_v8P5GhHOKwzCSR0hgdUHrnF4DUFmyby45uVtFouI3qe', number: '+15555550100' }
  ],
  '440': [
    { id: 'phon_Hcd8Gnd5UVhOs6sd8RaS15krqSRFTKI3qrVmBNhpWd8', number: '+15555550100' },
    { id: 'phon_mGR9Sverf72aPeVovjGChbNtfH6g2gmS2hEAlgzbLjq', number: '+15555550100' }
  ],
  '216': [
    { id: 'phon_GPHgzIPuuBsCBtw5u2K0rVreNa5LWcqYjZZ2JgAEQz3', number: '+15555550100' }
  ],
  'default': { id: 'phon_jIteklsdr2tUmnb09NjGuQYiPY1WylLCYAeIAyrZMe0', number: '+15555550100' }
};

// ZIP to Area Code Mapping
const ZIP_TO_AREA_CODE = {
  // BRRRR (Akron) - 330
  '44302': '330', '44303': '330', '44306': '330', '44310': '330',
  '44312': '330', '44313': '330', '44314': '330', '44319': '330', '44320': '330',
  // BRRRR (Canton) - 330
  '44703': '330', '44705': '330', '44708': '330', '44709': '330',
  '44710': '330', '44714': '330',
  // BRRRR (Other) - 330
  '44646': '330', '44647': '330', '44203': '330', '44224': '330',
  '44232': '330', '44685': '330',
  // High ARV (West) - 440
  '44136': '440', '44149': '440', '44212': '440', '44256': '440',
  '44141': '440', '44281': '440', '44147': '440', '44133': '440',
  // High ARV (Canton) - 330
  '44718': '330', '44720': '330', '44721': '330'
};

// HARD RULES CHECK
let shouldRun = true;
let skipReason = '';

// Rule 1: NEVER on Sunday
if (dayOfWeekEST === 0) {
  shouldRun = false;
  skipReason = 'Sunday - no sends allowed';
}

// Rule 2: Saturday restricted hours (10 AM - 6 PM EST only)
else if (dayOfWeekEST === 6) {
  if (currentHourEST < 10 || currentHourEST >= 18) {
    shouldRun = false;
    skipReason = 'Saturday outside 10AM-6PM EST window';
  }
}

// Rule 3: Weekdays - 8 AM to 8 PM EST only
else {
  if (currentHourEST < 8 || currentHourEST >= 20) {
    shouldRun = false;
    skipReason = 'Outside 8AM-8PM EST window';
  }
}

// Determine current window for randomization
let currentWindow = 'none';
if (currentHourEST >= 8 && currentHourEST < 11) currentWindow = 'morning';
else if (currentHourEST >= 11 && currentHourEST < 14) currentWindow = 'midday';
else if (currentHourEST >= 14 && currentHourEST < 17) currentWindow = 'afternoon';
else if (currentHourEST >= 17 && currentHourEST < 20) currentWindow = 'evening';

return [{
  json: {
    shouldRun,
    skipReason,
    currentWindow,
    currentTime: now.toISOString(),
    currentTimeEST: estString,
    currentHourEST,
    currentMinuteEST,
    dayOfWeekEST,
    dayName: ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][dayOfWeekEST],
    phoneConfig: PHONE_CONFIG,
    zipToAreaCode: ZIP_TO_AREA_CODE
  }
}];

// CALCULATE NEXT FOLLOW-UP v7.3 - Fixed data reference
// After SMS send, $input.item.json is Close API response
// Must reference Store Message Data node for original lead data

const inputItem = $('Store Message Data').first().json;

if (!inputItem) {
  console.log('No data from Store Message Data node');
  return [{ json: { error: true, message: 'Missing upstream data' } }];
}

// Get sequence position from the stored data
const textBeingSentNow = inputItem.sequencePosition || inputItem._queue?.sequence_position || 1;

if (!textBeingSentNow || textBeingSentNow < 1 || textBeingSentNow > 8) {
  console.log('Invalid sequence position:', textBeingSentNow);
  return [{ json: { error: true, message: 'Invalid sequence position' } }];
}

console.log('Processing Text #' + textBeingSentNow + ' for lead: ' + inputItem.leadId);

const currentPosition = textBeingSentNow;
const nextTextNumber = currentPosition + 1;

const SEQUENCE_HOURS = {
  2: 6, 3: 36, 4: 144, 5: 204, 6: 288, 7: 420, 8: 612
};

const hoursUntilNext = SEQUENCE_HOURS[nextTextNumber] || 168;
const now = new Date();
const nextSendDate = new Date(now.getTime() + (hoursUntilNext * 60 * 60 * 1000));
const sequenceComplete = nextTextNumber > 8;

let newPipelineStage;
if (currentPosition <= 3) newPipelineStage = 'Blitz';
else if (currentPosition <= 6) newPipelineStage = 'Extended';
else newPipelineStage = 'Nurture';

return [{
  json: {
    leadId: inputItem.leadId || inputItem._queue?.lead_id,
    insulaLeadId: inputItem.insulaLeadId || inputItem._queue?.insula_lead_id || '',
    insulaPropertyId: inputItem.insulaPropertyId || inputItem._queue?.insula_property_id || '',
    leadName: inputItem.firstName || inputItem._queue?.first_name || '',
    phone: inputItem.phone || inputItem._queue?.phone || '',
    address: inputItem.address || inputItem._queue?.address || '',
    city: inputItem.city || inputItem._queue?.city || '',
    zip: inputItem.zip || inputItem._queue?.zip || '',
    newPosition: currentPosition,
    nextTextNumber: nextTextNumber,
    nextSendDate: sequenceComplete ? null : nextSendDate.toISOString(),
    lastContacted: now.toISOString(),
    newPipelineStage: newPipelineStage,
    sequenceComplete: sequenceComplete,
    listingType: inputItem.listingType || inputItem._queue?.listing_type || 'BRRRR',
    tier: inputItem.tier || inputItem._queue?.tier || '',
    _queue: inputItem._queue || {},
    _debug: { textBeingSentNow, currentPosition, nextTextNumber, hoursUntilNext, version: '7.3', dataSource: 'Store Message Data' }
  }
}];

// LOG SMS FAILURE v7.3 - Fixed data reference
// Get error response from current input
const errorResponse = $input.item.json;

// Get lead info from Store Message Data
let leadInfo = {};
try {
  leadInfo = $('Store Message Data').first().json || {};
} catch(e) {
  console.log('Could not get lead info from Store Message Data');
}

let failStats;
try {
  const raw = $execution.customData.get('failureStats');
  failStats = raw ? JSON.parse(raw) : { total: 0, failures: [] };
} catch(e) {
  failStats = { total: 0, failures: [] };
}

failStats.total++;
if (failStats.failures.length < 10) {
  failStats.failures.push({ 
    leadId: leadInfo.leadId || 'unknown',
    phone: leadInfo.phone || 'unknown',
    error: JSON.stringify(errorResponse).slice(0, 200) 
  });
}

$execution.customData.set('failureStats', JSON.stringify(failStats));

console.log('SMS Failure for lead:', leadInfo.leadId || 'unknown');

return [{
  json: {
    status: 'failed',
    leadId: leadInfo.leadId,
    phone: leadInfo.phone,
    error: errorResponse,
    timestamp: new Date().toISOString()
  }
}];

// ============================================
// STALL DETECTION
// Check for conversations that went cold
// ============================================

const response = $input.first().json;
const leads = response.data || [];
const now = new Date();

const stalledLeads = [];

for (const lead of leads) {
  const custom = lead.custom || {};
  const pipelineStage = custom.cf_POWtXhMQwwrBsrlkocDvtA5Fs57DvdKjwomTTgTP5vW;
  const lastMsgDirection = custom.cf_vrVajMz5zvcWRSxoflOq1AbfxWT12lVCvQZD04hIPvG;
  const lastMsgAt = custom.cf_mLLAy4ctJLqn2zhjECML593u8vs4lsIDtMjTQpHudtf;
  const responseType = custom.cf_response_type;

  // Skip if not in Active Conversation
  if (pipelineStage !== 'Active Conversation') continue;

  // Skip if they sent last message
  if (lastMsgDirection !== 'outbound') continue;

  // Calculate hours since last message
  if (!lastMsgAt) continue;
  const hoursSince = (now.getTime() - new Date(lastMsgAt).getTime()) / (1000 * 60 * 60);

  // Stall if > 24 hours and previous response was positive/question
  if (hoursSince > 24 && ['positive', 'question'].includes(responseType)) {
    stalledLeads.push({
      json: {
        leadId: lead.id,
        leadName: lead.display_name,
        hoursSinceLastMsg: Math.round(hoursSince),
        previousResponseType: responseType,
        action: 'mark_stalled'
      }
    });
  }
}

if (stalledLeads.length === 0) {
  return [{ json: { noStalledLeads: true } }];
}

return stalledLeads;

// ============================================================================
// ENHANCED SLACK NOTIFICATION WITH POSITION MONITORING
// ============================================================================

const items = $('Rate Limiter (1 per sec)').all();

// Collect statistics
let successCount = 0;
let failureCount = 0;
let positionMismatches = 0;
const leads = [];
const mismatches = [];

items.forEach(item => {
  const data = item.json;

  // Check if SMS was sent successfully
  const success = data._smsSuccess || false;

  if (success) {
    successCount++;

    leads.push({
      name: data.leadName || data._queue?.first_name || 'Unknown',
      phone: data.phone || data._queue?.phone || 'Unknown',
      sentPosition: data._queue?.sequence_position,
      newPosition: data.newPosition,
      nextPosition: data.nextTextNumber,
      stage: data.newPipelineStage
    });

    // CHECK FOR MISMATCH: If we have debug info
    if (data._debug) {
      const sentPos = data._debug.textBeingSentNow;
      const updatedPos = data.newPosition;

      if (sentPos !== updatedPos) {
        positionMismatches++;
        mismatches.push({
          lead: data.leadName || 'Unknown',
          sentPosition: sentPos,
          updatedPosition: updatedPos
        });
      }
    }

  } else {
    failureCount++;
  }
});

// Calculate success rate
const totalProcessed = successCount + failureCount;
const successRate = totalProcessed > 0 ? ((successCount / totalProcessed) * 100).toFixed(1) : 0;

// Build detailed message
const leadsList = leads.slice(0, 10).map(l =>
  `  • ${l.name}: Text #${l.sentPosition} → Position ${l.newPosition} (next: ${l.nextPosition || 'complete'}) [${l.stage}]`
).join('\n');

const mismatchList = mismatches.length > 0 ? mismatches.map(m =>
  `  ⚠️ ${m.lead}: Sent #${m.sentPosition} but updated to ${m.updatedPosition}`
).join('\n') : '  ✅ No mismatches detected';

const timestamp = new Date().toISOString();

const message = `
🔔 *Follow-Up Engine Completed*

*Summary:*
✅ Sent: ${successCount}
❌ Failed: ${failureCount}
📊 Success Rate: ${successRate}%
⏰ Time: ${timestamp}

*Position Tracking:*
${positionMismatches > 0 ? '⚠️' : '✅'} Mismatches: ${positionMismatches}
${mismatchList}

*Recent Sends:*
${leadsList}
${leads.length > 10 ? `... and ${leads.length - 10} more` : ''}

${positionMismatches > 0 ? '\n⚠️ *ACTION REQUIRED:* Position mismatches detected! Check logs.' : ''}
`;

return [{
  json: {
    message: message,
    successCount,
    failureCount,
    successRate,
    positionMismatches,
    totalProcessed,
    leads,
    mismatches,
    timestamp
  }
}];

// TRACK SUCCESS v7.4 - Removed $execution.customData (sandbox blocked)
// Just pass through data from Calculate Next Follow-Up

const calcItem = $('Calculate Next Follow-Up').first().json;

if (!calcItem || typeof calcItem !== 'object') {
  console.log('No data from Calculate Next Follow-Up');
  return [{ json: { status: 'error', message: 'Missing upstream data' } }];
}

console.log('Track Success - lead:', calcItem.leadId, '| Position:', calcItem.newPosition);

return [{
  json: {
    status: 'success',
    leadId: calcItem.leadId,
    insulaLeadId: calcItem.insulaLeadId || calcItem._queue?.insula_lead_id || '',
    insulaPropertyId: calcItem.insulaPropertyId || calcItem._queue?.insula_property_id || '',
    leadName: calcItem.leadName,
    phone: calcItem.phone,
    address: calcItem.address,
    city: calcItem.city,
    zip: calcItem.zip,
    newPosition: calcItem.newPosition,
    nextTextNumber: calcItem.nextTextNumber,
    nextSendDate: calcItem.nextSendDate,
    sequenceComplete: calcItem.sequenceComplete,
    newPipelineStage: calcItem.newPipelineStage,
    listingType: calcItem.listingType,
    tier: calcItem.tier,
    _queue: calcItem._queue,
    _smsSuccess: true,
    _debug: calcItem._debug
  }
}];

// Query Convex for follow-ups due NOW
const CONVEX_URL = 'https://YOUR_CONVEX_DEPLOYMENT.convex.site';
const now = Date.now();

try {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: `${CONVEX_URL}/api/follow-up-queue-due`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      due_before: now,
      status: 'pending',
      limit: 1000
    },
    json: true
  });

  const dueLeads = data.leads || [];

  if (dueLeads.length === 0) {
    return [{ 
      json: { 
        noLeads: true, 
        totalDue: 0,
        leads: [], 
        message: 'No follow-ups due', 
        serverTime: new Date().toISOString() 
      } 
    }];
  }

  console.log(`Found ${dueLeads.length} follow-ups due from Convex queue`);

  // Return with totalDue at top level for easy visibility
  return [{
    json: {
      totalDue: dueLeads.length,
      message: `${dueLeads.length} follow-ups due`,
      leads: dueLeads,
      serverTime: new Date().toISOString()
    }
  }];
} catch (error) {
  console.log('Convex query error:', error.message);
  return [{ json: { error: true, totalDue: 0, leads: [], message: error.message } }];
}

// UPDATE CONVEX QUEUE v7.3 - Fixed data reference
const CONVEX_URL = 'https://YOUR_CONVEX_DEPLOYMENT.convex.site';

// Reference Track Success1 for proper data
const item = $('Track Success1').first().json;

if (!item || typeof item !== 'object') {
  console.log('No data from Track Success1');
  return [{ json: { status: 'error', message: 'Missing upstream data' } }];
}

const queueId = item._queue?._id;
const leadId = item.leadId || item._queue?.lead_id;
const phone = item.phone || item._queue?.phone;
const insulaLeadId = item.insulaLeadId || item._queue?.insula_lead_id || null;
const insulaPropertyId = item.insulaPropertyId || item._queue?.insula_property_id || null;

console.log('Processing queue update for lead:', leadId);

if (!queueId) {
  console.log('Missing queue ID - skipping');
  return [{ json: { status: 'skipped', reason: 'no_queue_id', leadId } }];
}

const results = { queueId, leadId, markedSent: false, addedNext: false, errors: [] };

// STEP 1: Mark current as SENT
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${CONVEX_URL}/api/follow-up-queue-complete`,
    headers: { 'Content-Type': 'application/json' },
    body: { queue_id: queueId, status: 'sent', sent_at: Date.now() },
    json: true
  });
  results.markedSent = true;
} catch (error) {
  results.errors.push(error.message);
  console.log('Failed to mark sent:', error.message);
}

// STEP 2: Add next follow-up
if (!item.sequenceComplete && item.nextTextNumber && item.nextTextNumber <= 8) {
  try {
    const allQueue = await this.helpers.httpRequest({
      method: 'GET',
      url: `${CONVEX_URL}/api/follow-up-queue-list?status=pending&limit=100`,
      json: true
    });
    const duplicate = allQueue.find(q => q.lead_id === leadId && q.sequence_position === item.nextTextNumber && q.status === 'pending');
    if (duplicate) {
      results.skippedReason = 'duplicate';
      return [{ json: results }];
    }
  } catch (e) {}

  const nextSendTimestamp = new Date(item.nextSendDate).getTime();
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${CONVEX_URL}/api/follow-up-queue-add`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        lead_id: leadId,
        phone: phone,
        first_name: item._queue?.first_name || item.leadName || '',
        address: item._queue?.address || item.address || '',
        city: item._queue?.city || item.city || '',
        zip: item._queue?.zip || item.zip || '',
        next_send_date: nextSendTimestamp,
        sequence_position: item.nextTextNumber,
        lead_type: 'Seller',
        listing_type: item.listingType || item._queue?.listing_type || 'BRRRR',
        insula_lead_id: insulaLeadId,
        insula_property_id: insulaPropertyId,
        tier: item.tier || item._queue?.tier || '',
        status: 'pending'
      },
      json: true
    });
    results.addedNext = true;
  } catch (error) {
    results.errors.push(error.message);
  }
} else {
  results.skippedReason = 'sequence_complete';
}

return [{ json: results }];

// Split Convex leads array into individual n8n items
const input = $input.first().json;
const leads = input.leads || [];

// If no leads, return EMPTY array - nothing enters the loop
if (!leads || leads.length === 0) {
  console.log('No follow-ups due - returning empty array');
  return [];  // Empty = Rate Limiter goes straight to "done" output
}

console.log(`Splitting ${leads.length} leads into individual items`);

// Output each lead as a separate item
return leads.map(queueItem => ({
  json: {
    lead_id: queueItem.lead_id,
    insula_lead_id: queueItem.insula_lead_id || null,
    insula_property_id: queueItem.insula_property_id || null,
    _queue: queueItem
  }
}));

// LOG DELETED STALE LEAD v7.3 - Fixed input validation
const rawInput = $input.item.json;

// Validate input is an object
if (!rawInput || typeof rawInput !== 'object' || Array.isArray(rawInput)) {
  console.log('Invalid input for deleted lead log');
  return [{ json: { status: 'deleted', data: null, timestamp: new Date().toISOString() } }];
}

console.log('Deleted stale lead:', rawInput.lead_id || 'unknown');
return [{ json: { status: 'deleted', data: rawInput, timestamp: new Date().toISOString() } }];

// Build Message v9.3 - Full Safety Filters (matching fls workflow)
const CONVEX_URL = 'https://YOUR_CONVEX_DEPLOYMENT.convex.site';

// Helper: Safely extract string from array or string (Close CRM returns arrays for multi-select)
const safeStr = (val) => {
  if (Array.isArray(val)) return (val[0] || '').toString();
  return (val || '').toString();
};

// Helper: Calculate hours since a date
const hoursSince = (dateStr) => {
  if (!dateStr) return Infinity;
  const date = new Date(dateStr);
  return (Date.now() - date.getTime()) / (1000 * 60 * 60);
};

// Get original Convex queue data (with _id)
let originalQueue = null;
try {
  originalQueue = $('Rate Limiter (1 per sec)').first().json._queue;
} catch(e) {
  console.log('Could not get original queue data');
}

// Input validation for Close data
const rawInput = $input.item.json;
let closeData;

if (!rawInput || typeof rawInput !== 'object' || Array.isArray(rawInput)) {
  console.log('Invalid input - not an object:', typeof rawInput);
  return [{ json: { action: 'SKIP', reason: 'Invalid input data', skipType: 'invalid_input' } }];
}

closeData = rawInput;

console.log('=== BUILD MESSAGE v9.3 ===');
console.log('Close ID:', closeData.id);
console.log('Queue ID:', originalQueue?._id);

if (!closeData.id) {
  return [{ json: { action: 'SKIP', reason: 'No Close ID', skipType: 'missing_data' } }];
}

// Extract data from Close CRM
const leadId = closeData.id;
const displayName = closeData.display_name || '';
const firstName = displayName.split(' ')[0] || 'there';

// Get contact info
const contact = closeData.contacts && closeData.contacts[0] ? closeData.contacts[0] : {};
const contactId = contact.id || null;
const phones = contact.phones || [];
const phone = phones.length > 0 ? phones[0].phone : '';

if (!phone) {
  return [{ json: { action: 'SKIP', reason: 'No phone', lead_id: leadId, skipType: 'missing_phone' } }];
}

// Get custom fields from Close (using safeStr for array fields)
const custom = closeData.custom || {};
const address = custom.address || custom.property_address || safeStr(custom['Property Address']) || safeStr(custom.cf_oYpMjF2AbqjJ9TTnn3BZgCNlductY17okbScR0MvrhD) || originalQueue?.address || 'your property';
const city = custom.city || custom.property_city || safeStr(custom['Property City']) || safeStr(custom.cf_V5lJPTCII754eYehZUytaQVlT2AhErHmoNfCRTLrBYp) || originalQueue?.city || 'your area';
const zip = custom.zip || custom.property_zip || originalQueue?.zip || '';
const sequencePosition = Math.floor(originalQueue?.sequence_position || custom.sequence_position || custom['Sequence Position'] || 1);
const listingTypeRaw = safeStr(originalQueue?.listing_type || custom.listing_type || custom['Listing Type'] || 'BRRRR');
const tier = originalQueue?.tier || custom.tier || '';

console.log('Lead:', firstName, '| Phone:', phone, '| Position:', sequencePosition);

// ========== SAFETY CHECKS (CRITICAL!) ==========
const statusLabel = (closeData.status_label || '').toLowerCase();
const rawPipeline = custom.cf_POWtXhMQwwrBsrlkocDvtA5Fs57DvdKjwomTTgTP5vW || custom['Pipeline Stage'] || custom.pipeline_stage || '';
const pipelineStage = safeStr(rawPipeline).toLowerCase();

// Get timing fields for safety checks
const lastMsgDirection = safeStr(custom.cf_vrVajMz5zvcWRSxoflOq1AbfxWT12lVCvQZD04hIPvG || custom['Last Message Direction'] || '');
const lastContactedAt = safeStr(custom.cf_mLLAy4ctJLqn2zhjECML593u8vs4lsIDtMjTQpHudtf || custom['Last Contacted'] || '');
const vaLastMsgAt = safeStr(custom.cf_kePjoaKjgduHWIlz5sVnilaTT5SuURgLAsl1D2NhLl9 || custom['VA Last Message At'] || '');

console.log('Status:', statusLabel, '| Pipeline:', pipelineStage);
console.log('Last Direction:', lastMsgDirection, '| Last Contact:', lastContactedAt);

// ========== 1. RECENT INBOUND CHECK (48hrs) ==========
if (lastMsgDirection.toLowerCase() === 'inbound' && hoursSince(lastContactedAt) < 48) {
  console.log('SKIP: Recent inbound -', Math.round(hoursSince(lastContactedAt)), 'hrs ago');
  return [{ json: { action: 'SKIP', reason: `Recent inbound (${Math.round(hoursSince(lastContactedAt))}hrs)`, lead_id: leadId, phone, skipType: 'recent_inbound' } }];
}

// ========== 2. DOUBLE TAP CHECK (outbound <12hrs) ==========
if (lastMsgDirection.toLowerCase() === 'outbound' && hoursSince(lastContactedAt) < 12) {
  console.log('SKIP: Double tap -', Math.round(hoursSince(lastContactedAt)), 'hrs ago');
  return [{ json: { action: 'SKIP', reason: `Double tap (${Math.round(hoursSince(lastContactedAt))}hrs)`, lead_id: leadId, phone, skipType: 'double_tap' } }];
}

// ========== 3. VA ACTIVE CHECK (<48hrs) ==========
if (vaLastMsgAt && hoursSince(vaLastMsgAt) < 48) {
  console.log('SKIP: VA active -', Math.round(hoursSince(vaLastMsgAt)), 'hrs ago');
  return [{ json: { action: 'SKIP', reason: `VA active (${Math.round(hoursSince(vaLastMsgAt))}hrs)`, lead_id: leadId, phone, skipType: 'va_active' } }];
}

// ========== 4. STATUS LABEL EXCLUSIONS ==========
const EXCLUDED_STATUSES = ['dnc', 'human hand', 'hostile', 'paused'];
for (const excluded of EXCLUDED_STATUSES) {
  if (statusLabel.includes(excluded)) {
    console.log('SKIP: Excluded status -', statusLabel);
    return [{ json: { action: 'SKIP', reason: `Status: ${closeData.status_label}`, lead_id: leadId, phone, skipType: 'excluded_status' } }];
  }
}

// ========== 5. PIPELINE STAGE EXCLUSIONS ==========
const EXCLUDED_STAGES = [
  'dnc', 'hot', 'warm', 'cold', 'human hand', 'hostile', 'paused',
  'appointment', 'callback', 'wrong contact', 'creative finance',
  'under contract', 'hostile - paused'
];
for (const excluded of EXCLUDED_STAGES) {
  if (pipelineStage.includes(excluded)) {
    console.log('SKIP: Excluded stage -', pipelineStage);
    return [{ json: { action: 'SKIP', reason: `Stage: ${pipelineStage}`, lead_id: leadId, phone, skipType: 'excluded_stage' } }];
  }
}

// ========== 6. DNC CHECK (Convex) ==========
try {
  const dncResp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${CONVEX_URL}/api/dnc-check?phone=${encodeURIComponent(phone)}`,
    json: true
  });
  if (dncResp && dncResp.isDnc === true) {
    return [{ json: { action: 'SKIP', reason: 'DNC (Convex)', lead_id: leadId, phone, skipType: 'dnc' } }];
  }
} catch (err) {
  console.log('DNC check error:', err.message);
}

// ========== 7. TCPA CHECK ==========
try {
  const cleanPhone = phone.replace(/\D/g, '');
  const areaCode = cleanPhone.length >= 10 ? cleanPhone.substring(cleanPhone.length - 10, cleanPhone.length - 7) : '216';
  const TIMEZONE_MAP = { '216': 'America/New_York', '440': 'America/New_York', '330': 'America/New_York' };
  const tz = TIMEZONE_MAP[areaCode] || 'America/New_York';
  const now = new Date();
  const opts = { timeZone: tz, hour: 'numeric', hour12: false, weekday: 'short' };
  const localTimeStr = now.toLocaleString('en-US', opts);
  const parts = localTimeStr.split(' ');
  const weekday = parts[0];
  const hour = parseInt(parts[1], 10);

  if (weekday === 'Sun') {
    return [{ json: { action: 'SKIP', reason: 'Sunday', lead_id: leadId, phone, skipType: 'tcpa_sunday' } }];
  }
  if (hour < 9 || hour >= 20) {
    return [{ json: { action: 'SKIP', reason: 'Outside hours', lead_id: leadId, phone, skipType: 'tcpa_hours' } }];
  }
} catch (err) {
  console.log('TCPA check error:', err.message);
}

// ========== 8. RECENT REPLY CHECK ==========
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${CONVEX_URL}/api/last-inbound?lead_id=${encodeURIComponent(leadId)}`,
    json: true
  });
  if (resp && resp.timestamp) {
    const hrs = (Date.now() - new Date(resp.timestamp).getTime()) / 3600000;
    if (hrs < 24) {
      return [{ json: { action: 'SKIP', reason: 'Recent reply', lead_id: leadId, phone, skipType: 'recent_reply' } }];
    }
  }
} catch (err) {}

// ========== 9. HOSTILE CHECK (Convex) ==========
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${CONVEX_URL}/api/hostile-check?lead_id=${encodeURIComponent(leadId)}`,
    json: true
  });
  if (resp && resp.inCoolingPeriod) {
    return [{ json: { action: 'SKIP', reason: 'Hostile cooling', lead_id: leadId, phone, skipType: 'hostile' } }];
  }
} catch (err) {}

console.log('All safety checks passed!');

// ========== GET ASSIGNED PHONE ==========
let assignedPhone = null;
if (custom['Assigned Phone']) {
  assignedPhone = String(custom['Assigned Phone']);
  if (!assignedPhone.startsWith('+')) assignedPhone = '+' + assignedPhone;
}
if (!assignedPhone) {
  try {
    const resp = await this.helpers.httpRequest({ method: 'GET', url: `${CONVEX_URL}/api/phone-select`, json: true });
    if (resp && resp.phone) assignedPhone = resp.phone;
  } catch (e) {}
}
if (!assignedPhone) assignedPhone = '+15555550100';

// ========== BUILD MESSAGE ==========
const streetName = address.replace(/^\d+\s+/, '').split(',')[0].trim();
let listingType;
if (listingTypeRaw === 'HIGH_ARV' || listingTypeRaw === 'High_ARV' || listingTypeRaw === 'ARV') {
  listingType = 'High_ARV';
} else if (listingTypeRaw && listingTypeRaw.indexOf('Expired') === 0) {
  listingType = listingTypeRaw; // Preserve Expired_Hot, Expired_Warm, Expired_Cold
} else {
  listingType = 'BRRRR';
}

let templateBody = null, templateId = null, templateVariant = null;
const FALLBACK = { 1: 'Hey, following up on {street_name}', 2: '{street_name} - still interested?', 3: 'Quick question about {street_name}', 4: 'Hey, {street_name}?', 5: 'Checking in on {street_name}', 6: 'Final note on {street_name}', 7: 'Market update for {street_name}', 8: 'Last message about {street_name}' };

try {
  const apiUrl = `${CONVEX_URL}/api/template-select-thompson?position=${sequencePosition}&listing_type=${encodeURIComponent(listingType)}`;
  const parsed = await this.helpers.httpRequest({ method: 'GET', url: apiUrl, json: true });
  if (parsed && parsed.selected && parsed.selected.body) {
    templateBody = parsed.selected.body;
    templateId = parsed.selected._id;
    templateVariant = parsed.selected.variant_name || 'A';
  }
} catch (e) {
  console.log('Template API error:', e.message);
}

if (!templateBody) {
  templateBody = FALLBACK[sequencePosition] || FALLBACK[1];
  templateId = 'fallback_' + sequencePosition;
  templateVariant = 'fallback';
}

const messageToSend = templateBody
  .replace(/\{street_name\}/gi, streetName)
  .replace(/\{address\}/gi, address)
  .replace(/\{city\}/gi, city)
  .replace(/\{first_name\}/gi, firstName);

console.log('Message ready:', messageToSend.substring(0, 50));

// Build queue data WITH _id from original Convex data
const queueData = {
  _id: originalQueue?._id,
  lead_id: leadId,
  phone: phone,
  first_name: firstName,
  address: address,
  city: city,
  zip: zip,
  sequence_position: sequencePosition,
  listing_type: listingType,
  tier: tier,
  insula_lead_id: originalQueue?.insula_lead_id || null,
  insula_property_id: originalQueue?.insula_property_id || null
};

return [{
  json: {
    action: 'SEND',
    leadId: leadId,
    insulaLeadId: originalQueue?.insula_lead_id || null,
    insulaPropertyId: originalQueue?.insula_property_id || null,
    contactId: contactId,
    assignedPhone: assignedPhone,
    phone: phone,
    firstName: firstName,
    address: address,
    city: city,
    zip: zip,
    streetName: streetName,
    sequencePosition: sequencePosition,
    listingType: listingType,
    tier: tier,
    messageToSend: messageToSend,
    templateId: templateId,
    templateVariant: templateVariant,
    templateBody: templateBody,
    _queue: queueData,
    _closeData: closeData,
    _debug: { version: '9.3', statusLabel, pipelineStage, lastMsgDirection, hasQueueId: !!originalQueue?._id }
  }
}];

// SKIP EXCLUDED STATUS v7.4 - Now calls queue-skip API to cancel
const CONVEX_URL = 'https://YOUR_CONVEX_DEPLOYMENT.convex.site';

const rawInput = $input.item.json;

if (!rawInput || typeof rawInput !== 'object' || Array.isArray(rawInput)) {
  console.log('Invalid input - not an object');
  return [{ json: { status: 'skipped', reason: 'invalid_input', data: null } }];
}

const item = rawInput;
const leadId = item.id || '';
const contact = (item.contacts && item.contacts[0]) || {};
const phones = contact.phones || [];
const phone = phones.length > 0 ? phones[0].phone : '';
const statusId = item.status_id || '';
const custom = item.custom || {};
const pipeline = custom.cf_POWtXhMQwwrBsrlkocDvtA5Fs57DvdKjwomTTgTP5vW || '';

// Determine skip reason
var skipType = 'excluded_status';
var reason = 'Close CRM status excluded';

if (statusId === 'stat_AVA3WALf67nRg7DZXeNckA5RS0ifVRtcBJqeReNs9D6') {
  skipType = 'human_hand';
  reason = 'HUMAN HAND status - requires manual handling';
} else if (pipeline === 'DNC') {
  skipType = 'dnc';
  reason = 'DNC pipeline - opted out';
} else if (pipeline === 'Hot Lead' || pipeline === 'Warm Lead') {
  skipType = 'hot_warm';
  reason = pipeline + ' - active engagement, skip auto-sequence';
}

console.log('SKIP:', leadId, '| Reason:', reason, '| Type:', skipType);

// Call queue-skip API to cancel/update the queue entry
if (leadId && phone) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: CONVEX_URL + '/api/queue-skip',
      body: {
        lead_id: leadId,
        phone: phone,
        skip_reason: reason,
        skip_type: skipType
      },
      json: true
    });
    console.log('Queue updated for skipped lead');
  } catch (err) {
    console.log('Queue-skip API error:', err.message);
  }
}

return [{ json: { status: 'skipped', reason: reason, skipType: skipType, lead_id: leadId, phone: phone } }];

